(1907535, 263717, 32644, '<td valign="top">I do NOT like the post processing on this. The hands look diseased.</td>', 'I do NOT like the post processing on this. The hands look diseased.', '2005-11-30 12:35:13.000000', NULL, 1),
(1907543, 263634, 39349, '<td valign="top">Great execution on a perfect idea for this challenge. I can''t tell you how much I like the setup for this shot! Bravo! I personally like your choice in dishware, it really works with the shot and gives it an antiqued feel.<br/> <br/>I''ll go out on a limb here to offer up some constructive criticism and say that the ONLY thing I can nit pic is the shadow on the right hand side of the bowl takes away some of the detail. Otherwise FANTASTIC JOB!<br/></td>', 'Great execution on a perfect idea for this challenge. I can''t tell you how much I like the setup for this shot! Bravo! I personally like your choice in dishware, it really works with the shot and gives it an antiqued feel. I''ll go out on a limb here to offer up some constructive criticism and say that the ONLY thing I can nit pic is the shadow on the right hand side of the bowl takes away some of the detail. Otherwise FANTASTIC JOB!', '2005-11-30 12:37:42.000000', NULL, 1),
(1907545, 263439, 39349, '<td valign="top">Bit too busy for me. But a nice collection none the less.</td>', 'Bit too busy for me. But a nice collection none the less.', '2005-11-30 12:38:49.000000', NULL, 1),
