(1913882, 263339, 47852, '<td valign="top">I like the way one little Pooh is facing towards the camera.  Cute collection and a nice shot!</td>', 'I like the way one little Pooh is facing towards the camera.  Cute collection and a nice shot!', '2005-12-01 19:07:21.000000', NULL, 1),
(1913886, 263220, 47852, '<td valign="top">Interesting how you took this of the tops instead of the bottles.  I like it.</td>', 'Interesting how you took this of the tops instead of the bottles.  I like it.', '2005-12-01 19:09:55.000000', NULL, 1),
(1913888, 263065, 48761, '<td valign="top">Nice touch with the atlas in the background... really transforms it from a snapshot to a photo.</td>', 'Nice touch with the atlas in the background... really transforms it from a snapshot to a photo.', '2005-12-01 19:10:12.000000', NULL, 1),
(1913891, 262959, 47852, '<td valign="top">The wrinkled background is a bit distracting to me.  Otherwise, I like the simple setup you used.</td>', 'The wrinkled background is a bit distracting to me.  Otherwise, I like the simple setup you used.', '2005-12-01 19:11:00.000000', NULL, 1),
(1913892, 261704, 48761, '<td valign="top">Cool effect, nice lighting.  Perhaps a bit underexposed for my taste, but I can see how it could be appreciated this way.</td>', 'Cool effect, nice lighting.  Perhaps a bit underexposed for my taste, but I can see how it could be appreciated this way.', '2005-12-01 19:11:11.000000', NULL, 1),
(1913893, 263092, 48761, '<td valign="top">The hand and the bulb really transform this one from a collection of old stuff to a well thought out photo!</td>', 'The hand and the bulb really transform this one from a collection of old stuff to a well thought out photo!', '2005-12-01 19:11:48.000000', NULL, 1),
(1913894, 263045, 48761, '<td valign="top">Great POV, great depth of field!</td>', 'Great POV, great depth of field!', '2005-12-01 19:12:15.000000', NULL, 1),
(1913895, 262039, 48761, '<td valign="top">Good shot, but the title really makes this one!</td>', 'Good shot, but the title really makes this one!', '2005-12-01 19:13:08.000000', NULL, 1),
(1913898, 263485, 47852, '<td valign="top">Like how you used the doors to frame the sides of the picture... like you''re peeking in on what the musician is doing.  Nicely done!</td>', 'Like how you used the doors to frame the sides of the picture... like you''re peeking in on what the musician is doing.  Nicely done!', '2005-12-01 19:14:10.000000', NULL, 1),
(1913901, 262923, 48761, '<td valign="top">The dirty fingernails are a nice touch (seriously), even if unintended.  :-)  The lighting is a tad flat, some dramatic lighting and I think you''d have a 9 on your hands.</td>', 'The dirty fingernails are a nice touch (seriously), even if unintended.  :-)  The lighting is a tad flat, some dramatic lighting and I think you''d have a 9 on your hands.', '2005-12-01 19:15:15.000000', NULL, 1),
(1913908, 263441, 48761, '<td valign="top">I feel like so many people missed the point of "collections", and took photos of a page of a stamp book, or a pile of polished rocks sitting on a table.  I think "CD Fish" exemplifies the qualities of creative photography, and outside of being a cool photograph is a really cool mural!  The execution is a 7 or so, but I feel like the concept is an easy ten.  Eight from me!</td>', 'I feel like so many people missed the point of "collections", and took photos of a page of a stamp book, or a pile of polished rocks sitting on a table.  I think "CD Fish" exemplifies the qualities of creative photography, and outside of being a cool photograph is a really cool mural!  The execution is a 7 or so, but I feel like the concept is an easy ten.  Eight from me!', '2005-12-01 19:18:24.000000', NULL, 1),
(1913915, 263472, 47852, '<td valign="top">I like the border on this one and the simplicity of the picture.  Nice job!</td>', 'I like the border on this one and the simplicity of the picture.  Nice job!', '2005-12-01 19:19:58.000000', NULL, 1),
(1913963, 263485, 45857, '<td valign="top">Good portrait of an artist, i like the way you used doors as framing.</td>', 'Good portrait of an artist, i like the way you used doors as framing.', '2005-12-01 19:38:59.000000', NULL, 1),
(1913991, 263634, 15574, '<td valign="top">Nice creativity</td>', 'Nice creativity', '2005-12-01 19:46:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1914022, 263116, 45857, '<td valign="top">down to the crossroads. I like your interpretation</td>', 'down to the crossroads. I like your interpretation', '2005-12-01 19:53:22.000000', NULL, 1),
(1914027, 262967, 45857, '<td valign="top">Nice humorous approach.</td>', 'Nice humorous approach.', '2005-12-01 19:54:12.000000', NULL, 1),
(1914031, 262340, 45857, '<td valign="top">good ''available'' light work.</td>', 'good ''available'' light work.', '2005-12-01 19:55:17.000000', NULL, 1),
(1914039, 261940, 45857, '<td valign="top">Colorful, I think it might have benn better without the edge of the box.</td>', 'Colorful, I think it might have benn better without the edge of the box.', '2005-12-01 19:57:19.000000', NULL, 1),
(1914042, 262526, 45857, '<td valign="top">Nice assortment of classic and kitsch. Crowds the edges a bit.</td>', 'Nice assortment of classic and kitsch. Crowds the edges a bit.', '2005-12-01 19:58:21.000000', NULL, 1),
(1914049, 262490, 45857, '<td valign="top">I like the shapes you have working here, interesting take on the theme.</td>', 'I like the shapes you have working here, interesting take on the theme.', '2005-12-01 20:00:04.000000', NULL, 1),
(1914054, 261758, 46330, '<td valign="top">Excellent composition and setup but I think it needs to have the contrast increased just a bit.  There''s too much middle grey and no true blacks or whites.</td>', 'Excellent composition and setup but I think it needs to have the contrast increased just a bit.  There''s too much middle grey and no true blacks or whites.', '2005-12-01 20:01:59.000000', NULL, 1),
(1914068, 263723, 45857, '<td valign="top">Great regimental look, but over here the yellows have a greeish tint.</td>', 'Great regimental look, but over here the yellows have a greeish tint.', '2005-12-01 20:10:26.000000', NULL, 1),
(1914073, 261741, 45857, '<td valign="top">Great studio shot, powerful reflection</td>', 'Great studio shot, powerful reflection', '2005-12-01 20:14:04.000000', NULL, 1),
(1914075, 263459, 45857, '<td valign="top">Awesome collection, poor focus</td>', 'Awesome collection, poor focus', '2005-12-01 20:14:45.000000', NULL, 1),
(1914080, 263752, 46330, '<td valign="top">Very nice colors but I think the crop should be a bit tighter on the butterflies as they are the subject of the photo.  The strong contrast between the blue sky and green foliage currently dominates the photo and the eye is drawn to it rather than the butterflies since they make up such a small proportion of the image.</td>', 'Very nice colors but I think the crop should be a bit tighter on the butterflies as they are the subject of the photo.  The strong contrast between the blue sky and green foliage currently dominates the photo and the eye is drawn to it rather than the butterflies since they make up such a small proportion of the image.', '2005-12-01 20:17:32.000000', NULL, 1),
(1914081, 263271, 15574, '<td valign="top">Yeah, thats pretty freaky. But the green eye is badass.</td>', 'Yeah, thats pretty freaky. But the green eye is badass.', '2005-12-01 20:18:36.000000', NULL, 1),
(1914097, 263521, 46330, '<td valign="top">There''s some potential here but the cars should be further down near the bottom third of the frame, i.e. "rule of thirds".  There are some situations where breaking the rule might work, but I don''t think this is one of them.  The centered composition here lacks interest.  I''d also suggest a viewpoint further to the left so that the barn could form a consistent background across the entire photo as the weathered wood fits in nicely with the feel of neglect.  Finally,  the date in the lower right just plain needs to go.</td>', 'There''s some potential here but the cars should be further down near the bottom third of the frame, i.e. "rule of thirds".  There are some situations where breaking the rule might work, but I don''t think this is one of them.  The centered composition here lacks interest.  I''d also suggest a viewpoint further to the left so that the barn could form a consistent background across the entire photo as the weathered wood fits in nicely with the feel of neglect.  Finally,  the date in the lower right just plain needs to go.', '2005-12-01 20:27:53.000000', NULL, 1),
(1914102, 262344, 45857, '<td valign="top">oops, wrong challenge.... still its good work</td>', 'oops, wrong challenge.... still its good work', '2005-12-01 20:30:34.000000', NULL, 1),
(1914110, 262383, 45857, '<td valign="top">47 Ronin? I like the bamboo background, an effect setting.</td>', '47 Ronin? I like the bamboo background, an effect setting.', '2005-12-01 20:33:27.000000', NULL, 1),
(1914117, 263439, 45857, '<td valign="top">Never seen an ampule collection. Very busy image, perhaps one would have been better than two.</td>', 'Never seen an ampule collection. Very busy image, perhaps one would have been better than two.', '2005-12-01 20:36:17.000000', NULL, 1),
(1914123, 262955, 45857, '<td valign="top">Amusing presentation, creative.</td>', 'Amusing presentation, creative.', '2005-12-01 20:36:59.000000', NULL, 1),
