(1917688, 262500, 29326, '<td valign="top">Very nice colors, lighting and pattern.</td>', 'Very nice colors, lighting and pattern.', '2005-12-02 22:04:33.000000', NULL, 1),
(1917690, 263140, 29326, '<td valign="top">A little too dark and fuzzy for my taste.</td>', 'A little too dark and fuzzy for my taste.', '2005-12-02 22:05:26.000000', NULL, 1),
