(1923076, 263284, 42792, '<td valign="top">Love this.  The colour ''wheel'' is nicely done.  Makes for a nice piece of poster art.</td>', 'Love this.  The colour ''wheel'' is nicely done.  Makes for a nice piece of poster art.', '2005-12-05 07:29:54.000000', NULL, 1),
(1923082, 262995, 42792, '<td valign="top">Good choice! :)  Nice angle.</td>', 'Good choice! :)  Nice angle.', '2005-12-05 07:35:02.000000', NULL, 1),
(1923101, 261214, 42792, '<td valign="top">For me this carries a very meaningful message.  Wished it was bigger so that as a viewer I can be totally "disgusted" by the details :)  Would love to see the original when the challenge is over.</td>', 'For me this carries a very meaningful message.  Wished it was bigger so that as a viewer I can be totally "disgusted" by the details :)  Would love to see the original when the challenge is over.', '2005-12-05 07:46:28.000000', NULL, 1),
(1923104, 263630, 42792, '<td valign="top">I like the composition but for some reason there seems to be more areas OOF than in focus.  It''s rather trying for the eyes to have to search before landing on the small narrow space of the 2nd and 3rd bottle from the front.</td>', 'I like the composition but for some reason there seems to be more areas OOF than in focus.  It''s rather trying for the eyes to have to search before landing on the small narrow space of the 2nd and 3rd bottle from the front.', '2005-12-05 07:50:45.000000', NULL, 1),
(1923110, 263271, 42792, '<td valign="top">Creepy!  Like the touch of green standing out.  The "bugs" just look a little too artficial but you couldn''t help that I guess ;)</td>', 'Creepy!  Like the touch of green standing out.  The "bugs" just look a little too artficial but you couldn''t help that I guess ;)', '2005-12-05 07:54:32.000000', NULL, 1),
(1923122, 262828, 42792, '<td valign="top">The desat works very well here to complement the mood created by the facial expressions.  A little creepy but effective. :)</td>', 'The desat works very well here to complement the mood created by the facial expressions.  A little creepy but effective. :)', '2005-12-05 08:00:48.000000', NULL, 1),
