(1926897, 261619, 10634, '<td valign="top">The color is perfect for this shot. It really hints at age and value. Love the way you composed this shot. I hope to see you in the top ten. Good Luck!</td>', 'The color is perfect for this shot. It really hints at age and value. Love the way you composed this shot. I hope to see you in the top ten. Good Luck!', '2005-12-06 09:54:51.000000', NULL, 1),
(1926900, 262831, 10634, '<td valign="top">I love the way you composed this. The wood post is the perfect background for these marbles. the dark color really sets them off.  Focus feels a little off though. Still, one of my favorites from the challenge. Good Luck.</td>', 'I love the way you composed this. The wood post is the perfect background for these marbles. the dark color really sets them off.  Focus feels a little off though. Still, one of my favorites from the challenge. Good Luck.', '2005-12-06 09:56:46.000000', NULL, 1),
(1926901, 263542, 10634, '<td valign="top">Great focus and composition. Not sure about the border since you kind of lose it in the bottom left corner. Hope to see you in the top ten.</td>', 'Great focus and composition. Not sure about the border since you kind of lose it in the bottom left corner. Hope to see you in the top ten.', '2005-12-06 09:58:00.000000', NULL, 1),
(1926904, 263472, 10634, '<td valign="top">I''ve found that ornaments are hard to photograph and do justice. I think you did an excellent job. They seem to just float there. Good Luck</td>', 'I''ve found that ornaments are hard to photograph and do justice. I think you did an excellent job. They seem to just float there. Good Luck', '2005-12-06 09:59:19.000000', NULL, 1),
