(1928963, 263521, 37875, '<td valign="top">slug bug!  where''s my sister when i need her??  : )<br/>in terms of composition, there are lots of interesting lines and angles in these cars.  i think that a closer shot of them, perhaps taken at unexpected angles, could really add some visual excitement to this photo.</td>', 'slug bug!  where''s my sister when i need her??  : )in terms of composition, there are lots of interesting lines and angles in these cars.  i think that a closer shot of them, perhaps taken at unexpected angles, could really add some visual excitement to this photo.', '2005-12-06 21:08:56.000000', NULL, 1),
(1928964, 262925, 37875, '<td valign="top">i''d love to see this as a b&amp;w with those great lines and tone variations!</td>', 'i''d love to see this as a b&w with those great lines and tone variations!', '2005-12-06 21:08:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1928966, 263750, 37875, '<td valign="top">like the choice of shooting detail in your collection.  a fun composition, and like the photography reference!</td>', 'like the choice of shooting detail in your collection.  a fun composition, and like the photography reference!', '2005-12-06 21:09:08.000000', NULL, 1),
(1928967, 263109, 37875, '<td valign="top">great colors, interesting subject, good dof, interesting lines.  i wouldn''t change a thing.</td>', 'great colors, interesting subject, good dof, interesting lines.  i wouldn''t change a thing.', '2005-12-06 21:09:14.000000', NULL, 1),
(1928969, 263738, 37875, '<td valign="top">cool candid-feeling picture.  like the dark feel to it.</td>', 'cool candid-feeling picture.  like the dark feel to it.', '2005-12-06 21:09:18.000000', NULL, 1),
(1928970, 263323, 37875, '<td valign="top">wish the lighting were different so that the viewer could really get a good look at the figurines.  the glare on the back of the shelf is distracting to my eye.</td>', 'wish the lighting were different so that the viewer could really get a good look at the figurines.  the glare on the back of the shelf is distracting to my eye.', '2005-12-06 21:09:21.000000', NULL, 1),
(1928971, 261439, 37875, '<td valign="top">mmm...beer...<br/>a pleasing arrangement for these beer coasters.  sharper focus and some bounced light could really make this image pop, to my eye.</td>', 'mmm...beer...a pleasing arrangement for these beer coasters.  sharper focus and some bounced light could really make this image pop, to my eye.', '2005-12-06 21:09:25.000000', NULL, 1),
(1928973, 262446, 37875, '<td valign="top">i really like the composition for this shot.  the whites in the photo appear to be a bit overexposed to my eye (i.e. audrey''s portrait, etc.), but what a great capture!</td>', 'i really like the composition for this shot.  the whites in the photo appear to be a bit overexposed to my eye (i.e. audrey''s portrait, etc.), but what a great capture!', '2005-12-06 21:09:30.000000', NULL, 1),
(1928974, 263271, 37875, '<td valign="top">this image is wicked cool.  love the green eye.  creepy, almost voodoo-feeling.  it''s awesome.</td>', 'this image is wicked cool.  love the green eye.  creepy, almost voodoo-feeling.  it''s awesome.', '2005-12-06 21:09:35.000000', NULL, 1),
(1928975, 263728, 37875, '<td valign="top">cool collection, and interesting composition!  like how the box is just cracking open to display part of the collection.  this works well for me.  i do wish that the lighting were more diffused so that you would not have the spot reflection on all the eggs.  very nicely done, though!</td>', 'cool collection, and interesting composition!  like how the box is just cracking open to display part of the collection.  this works well for me.  i do wish that the lighting were more diffused so that you would not have the spot reflection on all the eggs.  very nicely done, though!', '2005-12-06 21:09:39.000000', NULL, 1),
(1928976, 263167, 37875, '<td valign="top">great colors and interesting lines in this shot!</td>', 'great colors and interesting lines in this shot!', '2005-12-06 21:09:42.000000', NULL, 1),
(1928977, 262529, 37875, '<td valign="top">there is a reflection on the front left frame that is distracting to my eye...</td>', 'there is a reflection on the front left frame that is distracting to my eye...', '2005-12-06 21:09:45.000000', NULL, 1),
(1928978, 263757, 37875, '<td valign="top">this image is so cool...i wish there weren''t as much glare off of the 80th birthday stamp.  the composition and colors are so great, that the glare really stands out to my eye.  darn!</td>', 'this image is so cool...i wish there weren''t as much glare off of the 80th birthday stamp.  the composition and colors are so great, that the glare really stands out to my eye.  darn!', '2005-12-06 21:09:49.000000', NULL, 1),
(1928979, 263512, 37875, '<td valign="top">nicely composed, like the use of b&amp;w.  lots of visual interest in this set up.</td>', 'nicely composed, like the use of b&w.  lots of visual interest in this set up.', '2005-12-06 21:09:52.000000', NULL, 1),
(1928980, 263439, 37875, '<td valign="top">the mirrors add an interesting effect with the vials on the glass shelf--kind of futuristic, and quite cool.  i think this would have been a stronger photo if the vials  were the sole subject, instead of the vials and lighthouses...</td>', 'the mirrors add an interesting effect with the vials on the glass shelf--kind of futuristic, and quite cool.  i think this would have been a stronger photo if the vials  were the sole subject, instead of the vials and lighthouses...', '2005-12-06 21:09:57.000000', NULL, 1),
(1928982, 262681, 37875, '<td valign="top">I think that more dramatic lighting would really help this image pop.</td>', 'I think that more dramatic lighting would really help this image pop.', '2005-12-06 21:10:05.000000', NULL, 1),
(1928983, 262873, 37875, '<td valign="top">cd''s are always great subjects to shoot with the way they play with light.  the challenge comes in finding an exciting composition...i like the green cast but would have liked to see the titles of the cd''s or something to make this collection stand out.</td>', 'cd''s are always great subjects to shoot with the way they play with light.  the challenge comes in finding an exciting composition...i like the green cast but would have liked to see the titles of the cd''s or something to make this collection stand out.', '2005-12-06 21:10:11.000000', NULL, 1),
(1928984, 263056, 37875, '<td valign="top">great photo!  a different background would have helped reduce glare and have the colors pop.  love how you''ve included the collector in the image.</td>', 'great photo!  a different background would have helped reduce glare and have the colors pop.  love how you''ve included the collector in the image.', '2005-12-06 21:10:18.000000', NULL, 1),
(1928985, 262922, 37875, '<td valign="top">i would be interested in seeing this collection as a tighter shot...so that the bed and wall are out of view.</td>', 'i would be interested in seeing this collection as a tighter shot...so that the bed and wall are out of view.', '2005-12-06 21:10:29.000000', NULL, 1),
(1928986, 263651, 37875, '<td valign="top">lol!  some great cuffs.  i want to say that the white background is reflecting on the cuffs, making the image appear to be pretty bright in spots..</td>', 'lol!  some great cuffs.  i want to say that the white background is reflecting on the cuffs, making the image appear to be pretty bright in spots..', '2005-12-06 21:10:33.000000', NULL, 1),
(1928988, 262977, 37875, '<td valign="top">like the smoke with the signs.</td>', 'like the smoke with the signs.', '2005-12-06 21:10:39.000000', NULL, 1),
(1928989, 263265, 37875, '<td valign="top">great composition and nice combination of textures.</td>', 'great composition and nice combination of textures.', '2005-12-06 21:10:43.000000', NULL, 1),
(1928990, 262538, 37875, '<td valign="top">cool shapes, glows, and colors.  the straps are distracting to my eye, and i wish they could have been excluded from this picture.  love how the reflections work for the image as well.</td>', 'cool shapes, glows, and colors.  the straps are distracting to my eye, and i wish they could have been excluded from this picture.  love how the reflections work for the image as well.', '2005-12-06 21:10:47.000000', NULL, 1),
(1928991, 263396, 37875, '<td valign="top">great dummy shot!  wish the lighting were softer, but a great composition!  very creative!</td>', 'great dummy shot!  wish the lighting were softer, but a great composition!  very creative!', '2005-12-06 21:10:53.000000', NULL, 1),
(1928992, 261440, 37875, '<td valign="top">like the use of candlelight with the corks.  a nice, soft, romantic photo that goes with wine.</td>', 'like the use of candlelight with the corks.  a nice, soft, romantic photo that goes with wine.', '2005-12-06 21:10:56.000000', NULL, 1),
(1928994, 262135, 37875, '<td valign="top">cool trophy!  i would have liked to see a more energetic arrangement to go with such an energetic trophy, i think.</td>', 'cool trophy!  i would have liked to see a more energetic arrangement to go with such an energetic trophy, i think.', '2005-12-06 21:11:03.000000', NULL, 1),
(1928995, 263590, 37875, '<td valign="top">great title!  i would love to see another light be used in this setup to show more detail in the faces, or have that top light bounced/diffused for a more even glow...</td>', 'great title!  i would love to see another light be used in this setup to show more detail in the faces, or have that top light bounced/diffused for a more even glow...', '2005-12-06 21:11:07.000000', NULL, 1),
(1928996, 262548, 37875, '<td valign="top">now THIS is MY kind of collection!  : )  and it even has my favorite winery!  (chateau montelena...but my fave is their cuvee).<br/>i would have enjoyed a simpler composition of just the bottles and wine glass, i think.  the crock, grape, tray, and opener don''t add much for me.  the bottles, wine glass, and wine are quite nice.</td>', 'now THIS is MY kind of collection!  : )  and it even has my favorite winery!  (chateau montelena...but my fave is their cuvee).i would have enjoyed a simpler composition of just the bottles and wine glass, i think.  the crock, grape, tray, and opener don''t add much for me.  the bottles, wine glass, and wine are quite nice.', '2005-12-06 21:11:10.000000', NULL, 1),
(1928997, 262845, 37875, '<td valign="top">you know, this photo would work so much better if your horizon line were straight....KIDDING!!!  : )  (people always seem to say this on DPC)<br/> <br/>i really like the angle of this shot and how it emphasizes the lines in the shelf and cds.  interesting color mix from the cd covers.  the only thing i''d really want to change is taking the shot with some richer lighting, i think.  a nice job!</td>', 'you know, this photo would work so much better if your horizon line were straight....KIDDING!!!  : )  (people always seem to say this on DPC) i really like the angle of this shot and how it emphasizes the lines in the shelf and cds.  interesting color mix from the cd covers.  the only thing i''d really want to change is taking the shot with some richer lighting, i think.  a nice job!', '2005-12-06 21:11:13.000000', NULL, 1),
(1928998, 261475, 37875, '<td valign="top">like the composition and dof!</td>', 'like the composition and dof!', '2005-12-06 21:11:18.000000', NULL, 1),
(1929001, 261671, 37875, '<td valign="top">a nice capture, but lacking in visual interest for my eye.  i''d love to see this creature photographed in different light (e.g. sunset or dawn)...although I understand that this probably was not an option!  : )</td>', 'a nice capture, but lacking in visual interest for my eye.  i''d love to see this creature photographed in different light (e.g. sunset or dawn)...although I understand that this probably was not an option!  : )', '2005-12-06 21:11:25.000000', NULL, 1),
(1929002, 262523, 37875, '<td valign="top">great background and composition.  really like the one spool set at an angle.</td>', 'great background and composition.  really like the one spool set at an angle.', '2005-12-06 21:11:29.000000', NULL, 1),
(1929004, 263459, 37875, '<td valign="top">it''s a shame the image is so blurry...i love the composition of this photo, and the collection, very much!</td>', 'it''s a shame the image is so blurry...i love the composition of this photo, and the collection, very much!', '2005-12-06 21:11:33.000000', NULL, 1),
(1929005, 262490, 37875, '<td valign="top">a bit overexposed to my eye, but very nicely composed.  a cool idea for this challenge.</td>', 'a bit overexposed to my eye, but very nicely composed.  a cool idea for this challenge.', '2005-12-06 21:11:38.000000', NULL, 1),
(1929006, 263165, 37875, '<td valign="top">nicely lit and composed.</td>', 'nicely lit and composed.', '2005-12-06 21:11:45.000000', NULL, 1),
