(1929008, 262830, 37875, '<td valign="top">great idea for the collection challenge!  nice, simple composition.</td>', 'great idea for the collection challenge!  nice, simple composition.', '2005-12-06 21:11:54.000000', NULL, 1),
(1929009, 263198, 37875, '<td valign="top">nicely lit and composed.</td>', 'nicely lit and composed.', '2005-12-06 21:12:02.000000', NULL, 1),
