(1929011, 263302, 37875, '<td valign="top">...interesting display for your shot glasses.  paris and the boot are the most visually interesting, and i think i would have enjoyed a composition that played up these two in particular.</td>', '...interesting display for your shot glasses.  paris and the boot are the most visually interesting, and i think i would have enjoyed a composition that played up these two in particular.', '2005-12-06 21:12:12.000000', NULL, 1),
(1929013, 261743, 37875, '<td valign="top">sharper focus would help this image pop, to my eye.</td>', 'sharper focus would help this image pop, to my eye.', '2005-12-06 21:12:16.000000', NULL, 1),
(1929015, 262657, 37875, '<td valign="top">interesting photo, like the b&amp;w for it...enhances the lighting.</td>', 'interesting photo, like the b&w for it...enhances the lighting.', '2005-12-06 21:12:22.000000', NULL, 1),
(1929016, 262039, 37875, '<td valign="top">love the composition of this photo, and the dof.  nicely done!</td>', 'love the composition of this photo, and the dof.  nicely done!', '2005-12-06 21:12:28.000000', NULL, 1),
