(1929020, 263233, 37875, '<td valign="top">what a sweet shot of a girl and her favorite horse!  i love the expression on her face, and the emphasis of scale in her size compared to her horse''s.</td>', 'what a sweet shot of a girl and her favorite horse!  i love the expression on her face, and the emphasis of scale in her size compared to her horse''s.', '2005-12-06 21:12:42.000000', NULL, 1),
