(1929022, 262923, 37875, '<td valign="top">great title!  love the idea!  a sweet,  simple composition.  the lighting feels a bit harsh and direct, and makes the hands look a bit shiny to my eye.  i wonder what bounced or more indirect lighting would do to the feel of this photo?</td>', 'great title!  love the idea!  a sweet,  simple composition.  the lighting feels a bit harsh and direct, and makes the hands look a bit shiny to my eye.  i wonder what bounced or more indirect lighting would do to the feel of this photo?', '2005-12-06 21:12:50.000000', NULL, 1),
(1929024, 263643, 37875, '<td valign="top">great lighting and dof!  an interesting composition.</td>', 'great lighting and dof!  an interesting composition.', '2005-12-06 21:12:53.000000', NULL, 1),
(1929026, 262340, 37875, '<td valign="top">lovely lighting.  wish the light were just a wee bit stronger from the jack-o-lantern...but a fun and creative image!</td>', 'lovely lighting.  wish the light were just a wee bit stronger from the jack-o-lantern...but a fun and creative image!', '2005-12-06 21:13:09.000000', NULL, 1),
