(1929029, 262502, 37875, '<td valign="top">like the colors and light in this image.</td>', 'like the colors and light in this image.', '2005-12-06 21:13:24.000000', NULL, 1),
(1929031, 261991, 37875, '<td valign="top">great capture!  interesting images and energetic composition.</td>', 'great capture!  interesting images and energetic composition.', '2005-12-06 21:13:34.000000', NULL, 1),
(1929032, 261770, 37875, '<td valign="top">like the arrangement and glow coming off the back of the table.  interesting composition!</td>', 'like the arrangement and glow coming off the back of the table.  interesting composition!', '2005-12-06 21:13:42.000000', NULL, 1),
(1929033, 262246, 37875, '<td valign="top">the topic made me smile.  like the choice of red for background.  i wonder if there''s another way to present these pins that would add greater visual interest or meaning, though.<br/> <br/>i commend you for being such a prolific donor!  : )</td>', 'the topic made me smile.  like the choice of red for background.  i wonder if there''s another way to present these pins that would add greater visual interest or meaning, though. i commend you for being such a prolific donor!  : )', '2005-12-06 21:13:47.000000', NULL, 1),
(1929034, 263561, 37875, '<td valign="top">like the composition!  also like the inclusion of the i-pod.</td>', 'like the composition!  also like the inclusion of the i-pod.', '2005-12-06 21:13:52.000000', NULL, 1),
(1929035, 262793, 37875, '<td valign="top">cool composition, great colors, interesting focus effect.</td>', 'cool composition, great colors, interesting focus effect.', '2005-12-06 21:13:56.000000', NULL, 1),
(1929038, 263239, 37875, '<td valign="top">i like how the light''s interacting with your subjects.  the white bowl-looking thing behind the horse''s mane is a bit distracting to my eye...i think the photo would be stronger without it.</td>', 'i like how the light''s interacting with your subjects.  the white bowl-looking thing behind the horse''s mane is a bit distracting to my eye...i think the photo would be stronger without it.', '2005-12-06 21:14:06.000000', NULL, 1),
(1929039, 263458, 37875, '<td valign="top">the background works well with this image.  like how the stacks of pennies are not straight.  nice job!</td>', 'the background works well with this image.  like how the stacks of pennies are not straight.  nice job!', '2005-12-06 21:14:12.000000', NULL, 1),
(1929040, 263452, 37875, '<td valign="top">a great photo!  sweet face, nice lighting and composition.  my mother-in-law would love her!</td>', 'a great photo!  sweet face, nice lighting and composition.  my mother-in-law would love her!', '2005-12-06 21:14:17.000000', NULL, 1),
(1929041, 263119, 37875, '<td valign="top">it seems like there are quite a few interesting pieces in your collection.  i wonder how they could have been arranged to bring greater visual interest to the photo?</td>', 'it seems like there are quite a few interesting pieces in your collection.  i wonder how they could have been arranged to bring greater visual interest to the photo?', '2005-12-06 21:14:22.000000', NULL, 1),
(1929045, 263460, 37875, '<td valign="top">the color appears to be overadjusted, as it''s breaking up and getting grainy/pixilated in the image.  nicely composed, and interesting collection!</td>', 'the color appears to be overadjusted, as it''s breaking up and getting grainy/pixilated in the image.  nicely composed, and interesting collection!', '2005-12-06 21:14:30.000000', NULL, 1),
(1929046, 263485, 37875, '<td valign="top">made me smile!  like how we''re peeking in through the doors at the collector absorbed in his collection.  nice natural light.</td>', 'made me smile!  like how we''re peeking in through the doors at the collector absorbed in his collection.  nice natural light.', '2005-12-06 21:14:38.000000', NULL, 1),
(1929047, 263670, 37875, '<td valign="top">a black background and some spot lighting may help this image pop out at the viewer more.</td>', 'a black background and some spot lighting may help this image pop out at the viewer more.', '2005-12-06 21:14:42.000000', NULL, 1),
(1929048, 263368, 37875, '<td valign="top">the image appears blurred.  different dof and sharper focus on the leaves would have achieved that "floating leaves" effect, imo.</td>', 'the image appears blurred.  different dof and sharper focus on the leaves would have achieved that "floating leaves" effect, imo.', '2005-12-06 21:14:47.000000', NULL, 1),
(1929049, 263634, 37875, '<td valign="top">like the twist in the title and image.  creative set up.</td>', 'like the twist in the title and image.  creative set up.', '2005-12-06 21:14:56.000000', NULL, 1),
(1929050, 262828, 37875, '<td valign="top">what great faces!  wonderful composition.  like the partial desaturation as well.</td>', 'what great faces!  wonderful composition.  like the partial desaturation as well.', '2005-12-06 21:14:58.000000', NULL, 1),
(1929052, 262430, 37875, '<td valign="top">cute collection, nice use of black background.  i would be interested in a more energetic composition.</td>', 'cute collection, nice use of black background.  i would be interested in a more energetic composition.', '2005-12-06 21:15:01.000000', NULL, 1),
(1929053, 263756, 37875, '<td valign="top">a creative display of your collection!  great idea and cute critters!</td>', 'a creative display of your collection!  great idea and cute critters!', '2005-12-06 21:15:12.000000', NULL, 1),
(1929054, 263583, 37875, '<td valign="top">like the focus on the clear/silver crystal.  the one to its left reminds me of a stuffed grape leaf, i must say!  great colors and nice dof in this shot.</td>', 'like the focus on the clear/silver crystal.  the one to its left reminds me of a stuffed grape leaf, i must say!  great colors and nice dof in this shot.', '2005-12-06 21:15:16.000000', NULL, 1),
(1929056, 263652, 37875, '<td valign="top">cute composition, and like the dof!</td>', 'cute composition, and like the dof!', '2005-12-06 21:15:22.000000', NULL, 1),
(1929058, 261753, 37875, '<td valign="top">a nice shot of that hot wheels car!  nice dof.</td>', 'a nice shot of that hot wheels car!  nice dof.', '2005-12-06 21:15:27.000000', NULL, 1),
(1929061, 262387, 37875, '<td valign="top">wow!  that''s a lot of recipes!  i like how you chose to show the sheer volume of paper as opposed to showing the actual recipe text.</td>', 'wow!  that''s a lot of recipes!  i like how you chose to show the sheer volume of paper as opposed to showing the actual recipe text.', '2005-12-06 21:16:31.000000', NULL, 1),
(1929062, 263733, 37875, '<td valign="top">what a fun composition!  the lighting appears to be a bit overexposed to my eye, but what great energy in this photo!</td>', 'what a fun composition!  the lighting appears to be a bit overexposed to my eye, but what great energy in this photo!', '2005-12-06 21:16:37.000000', NULL, 1),
(1929064, 263456, 37875, '<td valign="top">i wish the focus were sharper, because this looks like a cool collection!</td>', 'i wish the focus were sharper, because this looks like a cool collection!', '2005-12-06 21:16:40.000000', NULL, 1),
(1929065, 262393, 37875, '<td valign="top">the photo is quite dark, and it''s difficult to distinguish much detail as a result.</td>', 'the photo is quite dark, and it''s difficult to distinguish much detail as a result.', '2005-12-06 21:16:44.000000', NULL, 1),
(1929066, 262647, 37875, '<td valign="top">ha!  ; )<br/>nice yard, nicely composed shot.  like the pink and grey.</td>', 'ha!  ; )nice yard, nicely composed shot.  like the pink and grey.', '2005-12-06 21:16:49.000000', NULL, 1),
(1929067, 262287, 37875, '<td valign="top">i think this image could have more of the foreground cropped out to bring greater attention to the collection.  an interesting composition, and one of my favorite albums!</td>', 'i think this image could have more of the foreground cropped out to bring greater attention to the collection.  an interesting composition, and one of my favorite albums!', '2005-12-06 21:16:55.000000', NULL, 1),
