(1929158, 263454, 37875, '<td valign="top">i''d probably remove the price tag before shooting the photo...it distracts from the french focus, in my eye.  what a great idea for this challenge!  like the simple composition, too.</td>', 'i''d probably remove the price tag before shooting the photo...it distracts from the french focus, in my eye.  what a great idea for this challenge!  like the simple composition, too.', '2005-12-06 21:22:44.000000', NULL, 1),
(1929159, 261758, 37875, '<td valign="top">what a neat composition!  a novel topic for this challenge, and the magnifying glass really adds to the photo, as does the smoke effect.  nicely done!</td>', 'what a neat composition!  a novel topic for this challenge, and the magnifying glass really adds to the photo, as does the smoke effect.  nicely done!', '2005-12-06 21:22:48.000000', NULL, 1),
(1929161, 262027, 37875, '<td valign="top">a nice, simple composition.  i like it.  i wish the shot were in sharper focus, though.</td>', 'a nice, simple composition.  i like it.  i wish the shot were in sharper focus, though.', '2005-12-06 21:22:54.000000', NULL, 1),
(1929162, 263495, 37875, '<td valign="top">like the subject, would have liked sharper focus and a stronger background to allow the colors to pop.</td>', 'like the subject, would have liked sharper focus and a stronger background to allow the colors to pop.', '2005-12-06 21:22:58.000000', NULL, 1),
(1929163, 261521, 37875, '<td valign="top">use of a scrim would really allow those coins to glow...</td>', 'use of a scrim would really allow those coins to glow...', '2005-12-06 21:23:12.000000', NULL, 1),
(1929164, 263150, 37875, '<td valign="top">cute!  love the live bunny with all the figurines.  adds visual interest and a bit of the unexpected.</td>', 'cute!  love the live bunny with all the figurines.  adds visual interest and a bit of the unexpected.', '2005-12-06 21:23:15.000000', NULL, 1),
(1929165, 262967, 37875, '<td valign="top">what a fun collection!  i wish the lighting wre a bit different, so that the shapes and colors in the figurines could really pop out.</td>', 'what a fun collection!  i wish the lighting wre a bit different, so that the shapes and colors in the figurines could really pop out.', '2005-12-06 21:23:17.000000', NULL, 1),
(1929166, 263084, 37875, '<td valign="top">i would like to see softer and more diffused lighting for this image.  the shadow''s a bit distracting to my eye.</td>', 'i would like to see softer and more diffused lighting for this image.  the shadow''s a bit distracting to my eye.', '2005-12-06 21:23:21.000000', NULL, 1),
(1929167, 263722, 37875, '<td valign="top">lol!  i have that same conversation with my boyfriend about my shoes!<br/> <br/>like the staggered steps of the jewelry box.  the blue and silver necklace really jumps out in the image.</td>', 'lol!  i have that same conversation with my boyfriend about my shoes! like the staggered steps of the jewelry box.  the blue and silver necklace really jumps out in the image.', '2005-12-06 21:23:24.000000', NULL, 1),
(1929168, 262924, 37875, '<td valign="top">nicely composed.  interesting lines.  wonder how this would have looked as a b&amp;w with all the lines and textures?</td>', 'nicely composed.  interesting lines.  wonder how this would have looked as a b&w with all the lines and textures?', '2005-12-06 21:23:27.000000', NULL, 1),
(1929170, 263472, 37875, '<td valign="top">these ornaments look really interesting in b&amp;w, and they appear to float against the background.  a very cool picture.</td>', 'these ornaments look really interesting in b&w, and they appear to float against the background.  a very cool picture.', '2005-12-06 21:23:30.000000', NULL, 1),
(1929171, 263147, 37875, '<td valign="top">i love turtles!  : )<br/>i like how you''ve varied the height and size of the turtles in this composition, but would have liked to see either wider focus or the focus be on only one turtle, just for additional visual impact.  looks like you have a cool collection!</td>', 'i love turtles!  : )i like how you''ve varied the height and size of the turtles in this composition, but would have liked to see either wider focus or the focus be on only one turtle, just for additional visual impact.  looks like you have a cool collection!', '2005-12-06 21:23:34.000000', NULL, 1),
(1929242, 263140, 49007, '<td valign="top">Severely out of focus.</td>', 'Severely out of focus.', '2005-12-06 21:44:06.000000', NULL, 1),
(1929302, 263165, 49007, '<td valign="top">What a great use of depth of focus and great color, however the back light  needs to be muted more.</td>', 'What a great use of depth of focus and great color, however the back light  needs to be muted more.', '2005-12-06 21:59:47.000000', NULL, 1),
(1929306, 263458, 49007, '<td valign="top">Great composition of the subject for shadows and reflections</td>', 'Great composition of the subject for shadows and reflections', '2005-12-06 22:01:08.000000', NULL, 1),
(1929311, 262923, 49007, '<td valign="top">The lighting on her hands is a bit harsh. Try difusing the light to soften her hands. Great depth of focus</td>', 'The lighting on her hands is a bit harsh. Try difusing the light to soften her hands. Great depth of focus', '2005-12-06 22:03:59.000000', NULL, 1),
(1929317, 261440, 49007, '<td valign="top">Nice use of natural light, shadows and composition.</td>', 'Nice use of natural light, shadows and composition.', '2005-12-06 22:05:41.000000', NULL, 1),
(1929322, 261682, 43774, '<td valign="top">Pretty flower, not quite in focus, not much of a collection either, sorry.</td>', 'Pretty flower, not quite in focus, not much of a collection either, sorry.', '2005-12-06 22:07:54.000000', NULL, 1),
(1929323, 263220, 49007, '<td valign="top">The image is extremely soft due to either being out of focus or too shallow a depth of focus.</td>', 'The image is extremely soft due to either being out of focus or too shallow a depth of focus.', '2005-12-06 22:08:02.000000', NULL, 1),
(1929325, 261294, 43774, '<td valign="top">Interesting take on the challenge, seems pixelated to me, problems with resizing and compression maybe?</td>', 'Interesting take on the challenge, seems pixelated to me, problems with resizing and compression maybe?', '2005-12-06 22:08:35.000000', NULL, 1),
