(1929423, 262523, 48560, '<td valign="top">the tilted one on the top right corner adds a sense of "life" into the picture, very nice. 8</td>', 'the tilted one on the top right corner adds a sense of "life" into the picture, very nice. 8', '2005-12-06 22:40:02.000000', NULL, 1),
(1929490, 261411, 48717, '<td valign="top">Really nice pic, wish the shadow was not on the one skull.  Good lighting, contrast and arrangement</td>', 'Really nice pic, wish the shadow was not on the one skull.  Good lighting, contrast and arrangement', '2005-12-06 22:58:26.000000', NULL, 1),
(1929546, 263744, 12160, '<td valign="top">Very nice graphic look. Great circular patterns all around and good color. 8</td>', 'Very nice graphic look. Great circular patterns all around and good color. 8', '2005-12-06 23:15:09.000000', NULL, 1),
(1929560, 262793, 12160, '<td valign="top">Lensbabies? Great colour, well composed shot. 7</td>', 'Lensbabies? Great colour, well composed shot. 7', '2005-12-06 23:19:22.000000', NULL, 1),
