(1929682, 263284, 39349, '<td valign="top">Beautiful tones, dof and composition. 10 from me.</td>', 'Beautiful tones, dof and composition. 10 from me.', '2005-12-06 23:51:07.000000', NULL, 1),
(1929686, 263181, 22734, '<td valign="top">Almost poetic and by far my most favorite entry in this challenge. Bumping up. Well, I replaced a similar image in old shoes with another way back. This is the way i should have done it. Bumping up to 10.</td>', 'Almost poetic and by far my most favorite entry in this challenge. Bumping up. Well, I replaced a similar image in old shoes with another way back. This is the way i should have done it. Bumping up to 10.', '2005-12-06 23:52:08.000000', NULL, 1),
(1929689, 261411, 22734, '<td valign="top">Interesting collection...</td>', 'Interesting collection...', '2005-12-06 23:52:42.000000', NULL, 1),
(1929691, 262828, 22734, '<td valign="top">Now this collection really projects a triad of strong emotions. The colors are very cool. Returning for final bump.</td>', 'Now this collection really projects a triad of strong emotions. The colors are very cool. Returning for final bump.', '2005-12-06 23:53:08.000000', NULL, 1),
(1929692, 262995, 39349, '<td valign="top">I love this shot. Nice choice of music! I can''t wait to see what lens you used to get this effect. 10 from me for a fun shot that brings a smile to ones face. Well done!</td>', 'I love this shot. Nice choice of music! I can''t wait to see what lens you used to get this effect. 10 from me for a fun shot that brings a smile to ones face. Well done!', '2005-12-06 23:53:17.000000', NULL, 1),
(1929695, 262259, 39349, '<td valign="top">Simply stunning photo. Beautiful tones throughout this shot. Great originality for this challenge as well. 10 from me.</td>', 'Simply stunning photo. Beautiful tones throughout this shot. Great originality for this challenge as well. 10 from me.', '2005-12-06 23:54:05.000000', NULL, 1),
(1929703, 263472, 39349, '<td valign="top">Tack sharp detail make this a pleasure to view. You''ve captured the delicateness of these ornaments. well done.</td>', 'Tack sharp detail make this a pleasure to view. You''ve captured the delicateness of these ornaments. well done.', '2005-12-06 23:55:49.000000', NULL, 1),
(1929709, 261741, 39349, '<td valign="top">Beautiful tones throughout this well done shot of currency.</td>', 'Beautiful tones throughout this well done shot of currency.', '2005-12-06 23:56:28.000000', NULL, 1),
(1929716, 263045, 39850, '<td valign="top">7 - Good.  Criticism; your call obviously, but in my opinion, a tighter crop at the bottom, perhaps with even more space at the top, would have made this even better.  Like the depth of field and background, although do wonder whether a different color choice of background would have enhanced the soldiers.  Not sure on the thick frame.  Also seems a ''flaw'' on the right near the bottom in the foreground.  Up to 7 from 6. edit:6 to 7 at beginning of comment<br/><br/><i>Message edited by author 2005-12-07 00:31:54.</i></td>', '7 - Good.  Criticism; your call obviously, but in my opinion, a tighter crop at the bottom, perhaps with even more space at the top, would have made this even better.  Like the depth of field and background, although do wonder whether a different color choice of background would have enhanced the soldiers.  Not sure on the thick frame.  Also seems a ''flaw'' on the right near the bottom in the foreground.  Up to 7 from 6. edit:6 to 7 at beginning of comment', '2005-12-06 23:58:44.000000', '2005-12-07 00:31:54.000000', 1),
(1929723, 263181, 5885, '<td valign="top">Angela, YOU ROCK!!! Congrats on the Ribbon. I knew you could do it!</td>', 'Angela, YOU ROCK!!! Congrats on the Ribbon. I knew you could do it!', '2005-12-07 00:11:38.000000', NULL, 0),
